-- Templates, reusable content and editor helpers:
--  * snippets: named reusable blocks (signature, sponsor banner, footer CTA…). Inserted into posts/automation emails
--    either as a copy or as a synced reference block {type:'snippet', data:{snippet_id}} rendered from the current
--    snippet content at render/send time (lib/render.ts).
--  * 14 more library templates (≥ 45 total), incl. one custom-coded HTML template ({type:'html_document'} block)
--    and one using the personalized `recommended_products` block. Sample artwork lives in /static/templates/.
CREATE TABLE IF NOT EXISTS snippets (
  id TEXT PRIMARY KEY,
  pub_id TEXT NOT NULL REFERENCES publications(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  content TEXT NOT NULL DEFAULT '{"blocks":[]}',
  created_by TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_snippets_pub ON snippets(pub_id, updated_at);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_product_launch', NULL, 'Product announcement', 'post', 'Big-launch email: hero image, the one-line promise, three feature columns, a customer quote and a clear call to action.', '{"blocks":[{"id":"x1","type":"image","data":{"src":"/static/templates/launch-hero.jpg","alt":"Product screenshot","title":"","caption":"","width":100,"align":"center","link":"","radius":12}},{"id":"x2","type":"paragraph","data":{"html":"<b>NEW</b> · Available today for everyone","align":"center"}},{"id":"x3","type":"heading","data":{"level":1,"html":"Meet the faster way to do the thing your readers care about","align":"center"}},{"id":"x4","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}} — in one sentence, say what you built and the outcome it gives people. Then stop. The rest of this email shows how.","align":"center"}},{"id":"x5","type":"button","data":{"label":"Try it free →","url":"https://example.com","align":"center"}},{"id":"x6","type":"spacer","data":{"height":8}},{"id":"xd","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"x7","type":"paragraph","data":{"html":"<b>⚡ Twice as fast</b>"}},{"id":"x8","type":"paragraph","data":{"html":"Explain the first benefit in a sentence. Lead with the result, not the feature."}}]},{"blocks":[{"id":"x9","type":"paragraph","data":{"html":"<b>🔒 Private by default</b>"}},{"id":"xa","type":"paragraph","data":{"html":"The second benefit. Mention what it replaces or removes from their day."}}]},{"blocks":[{"id":"xb","type":"paragraph","data":{"html":"<b>🤝 Built for teams</b>"}},{"id":"xc","type":"paragraph","data":{"html":"The third benefit. Concrete beats clever — use a number if you have one."}}]}]}},{"id":"xf","type":"section","data":{"blocks":[{"id":"xe","type":"quote","data":{"html":"“We switched in an afternoon and saved four hours a week. I can’t imagine going back.”","cite":"Alex Rivera, Head of Ops at Northwind","style":{"variant":"line","italic":false,"border_color":"#6366f1"}}}],"style":{"bg":"#f5f3ff","padding":22,"radius":12}}},{"id":"xg","type":"heading","data":{"level":3,"html":"What’s included"}},{"id":"xh","type":"list","data":{"ordered":false,"items":["<b>Feature one</b> — short description and who it helps","<b>Feature two</b> — what changed since the beta","<b>Feature three</b> — the small detail people will love"]}},{"id":"xi","type":"heading","data":{"level":3,"html":"Questions you might have"}},{"id":"xj","type":"paragraph","data":{"html":"<b>How much does it cost?</b> Answer plainly. Mention the free plan or trial."}},{"id":"xk","type":"paragraph","data":{"html":"<b>Will it work with my setup?</b> List the integrations or the one-line migration story."}},{"id":"xl","type":"button","data":{"label":"Get started today","url":"https://example.com","align":"center","bg":"#4f46e5"}},{"id":"xm","type":"paragraph","data":{"html":"Thanks for being here from the start,<br>The {{publication.name}} team","align":"center"}}]}', '{"email":{"radius":12,"width":640,"spacing":16,"font_size":16,"line_height":1.65,"font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","heading_font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","text":"#111827","muted":"#6b7280","bg":"#eef2ff","content_bg":"#ffffff","accent":"#6366f1","link":"#4f46e5","button_bg":"#4f46e5","button_text":"#ffffff","border":"#e0e7ff"},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"Inter, -apple-system, sans-serif","text":"#111827","accent":"#4f46e5","accent_text":"#ffffff"}}', 0, 'Business', 1793500000000, 1793500000000);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_case_study', NULL, 'Customer case study', 'post', 'Story-driven customer success email: results up front, challenge → solution → outcome, a pull quote and a “see how” CTA.', '{"blocks":[{"id":"xn","type":"paragraph","data":{"html":"<span style=\"letter-spacing:2px\">CUSTOMER STORY</span>"}},{"id":"xo","type":"heading","data":{"level":1,"html":"How Northwind cut onboarding time by 63%"}},{"id":"xp","type":"paragraph","data":{"html":"A three-sentence summary of who the customer is, what they were struggling with, and the headline result. Readers who stop here should still get the point."}},{"id":"xx","type":"section","data":{"blocks":[{"id":"xw","type":"columns","data":{"valign":"middle","columns":[{"blocks":[{"id":"xq","type":"heading","data":{"level":2,"html":"63%","align":"center"}},{"id":"xr","type":"paragraph","data":{"html":"faster onboarding","align":"center"}}]},{"blocks":[{"id":"xs","type":"heading","data":{"level":2,"html":"4.8★","align":"center"}},{"id":"xt","type":"paragraph","data":{"html":"team satisfaction","align":"center"}}]},{"blocks":[{"id":"xu","type":"heading","data":{"level":2,"html":"$120k","align":"center"}},{"id":"xv","type":"paragraph","data":{"html":"saved in year one","align":"center"}}]}]}}],"style":{"bg":"#ecfdf5","padding":18,"radius":12,"border_width":1,"border_color":"#a7f3d0"}}},{"id":"xy","type":"heading","data":{"level":2,"html":"The challenge"}},{"id":"xz","type":"paragraph","data":{"html":"Describe the situation before. Use the customer’s own words where possible, and quantify the pain: hours lost, deals stalled, errors made."}},{"id":"x10","type":"heading","data":{"level":2,"html":"The solution"}},{"id":"x11","type":"paragraph","data":{"html":"What they changed, step by step. Keep the product in a supporting role — the customer is the hero of this story."}},{"id":"x12","type":"list","data":{"ordered":true,"items":["Week 1: the first change they made","Week 3: the habit that stuck","Month 2: the result that convinced leadership"]}},{"id":"x13","type":"quote","data":{"html":"“Within a month, new hires were shipping in their first week. That never happened before.”","cite":"Dana Kim, VP Engineering at Northwind","style":{"variant":"pull","border_color":"#059669","border_width":2,"italic":true}}},{"id":"x14","type":"heading","data":{"level":2,"html":"The results"}},{"id":"x15","type":"paragraph","data":{"html":"Close with the measurable outcome and what’s next for them. Invite readers to picture the same result for themselves."}},{"id":"x16","type":"button","data":{"label":"Read the full story","url":"https://example.com","align":"center","bg":"#047857"}}]}', '{"email":{"radius":10,"width":640,"spacing":16,"font_size":16,"line_height":1.65,"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","text":"#0f172a","muted":"#64748b","bg":"#f0fdf4","content_bg":"#ffffff","accent":"#059669","link":"#047857","button_bg":"#047857","button_text":"#ffffff","border":"#d1fae5"},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"Inter, -apple-system, sans-serif","text":"#0f172a","accent":"#047857","accent_text":"#ffffff"}}', 0, 'Business', 1793500000001, 1793500000001);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_holiday', NULL, 'Holiday greetings', 'post', 'Festive end-of-year letter: illustrated hero, a warm thank-you, a short gift guide and a holiday offer code.', '{"blocks":[{"id":"x17","type":"image","data":{"src":"/static/templates/holiday-hero.jpg","alt":"Season’s greetings","title":"","caption":"","width":100,"align":"center","link":"","radius":10}},{"id":"x18","type":"heading","data":{"level":2,"html":"Thank you for a wonderful year, {{subscriber.first_name|friend}}","align":"center"}},{"id":"x19","type":"paragraph","data":{"html":"Write a short, genuine note: one memory from this year, one thing readers taught you, and what you’re looking forward to. Keep it personal — this is the email people reply to.","align":"center"}},{"id":"x1a","type":"divider","data":{"style":"stars","color":"#b91c1c"}},{"id":"x1b","type":"heading","data":{"level":3,"html":"🎁 A little gift guide","align":"center"}},{"id":"x1e","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"x1c","type":"paragraph","data":{"html":"<b>For the curious</b><br>A book or course you loved this year, with one line on why."}}]},{"blocks":[{"id":"x1d","type":"paragraph","data":{"html":"<b>For the busy</b><br>A tool or habit that saves time — the gift of an hour back."}}]}]}},{"id":"x1j","type":"section","data":{"blocks":[{"id":"x1f","type":"paragraph","data":{"html":"<b>OUR HOLIDAY GIFT TO YOU</b>","align":"center"}},{"id":"x1g","type":"heading","data":{"level":2,"html":"25% off premium with code <span style=\"font-family:monospace\">CHEERS25</span>","align":"center"}},{"id":"x1h","type":"button","data":{"label":"Claim your gift","url":"https://example.com","align":"center","bg":"#b91c1c"}},{"id":"x1i","type":"paragraph","data":{"html":"Valid until January 2. Also makes a lovely gift for a friend.","align":"center"}}],"style":{"bg":"#fef2f2","padding":24,"radius":12,"border_width":2,"border_style":"dashed","border_color":"#fca5a5"}}},{"id":"x1k","type":"paragraph","data":{"html":"We’re taking a short break and will be back in your inbox on January 6. Wishing you rest, warmth and good company.","align":"center"}},{"id":"x1l","type":"paragraph","data":{"html":"With gratitude,<br><b>{{publication.name}}</b>","align":"center"}}]}', '{"email":{"radius":10,"width":640,"spacing":16,"font_size":17,"line_height":1.65,"font":"Georgia, ''Times New Roman'', serif","heading_font":"Georgia, ''Times New Roman'', serif","text":"#1c1917","muted":"#78716c","bg":"#14532d","content_bg":"#fffdf7","accent":"#b91c1c","link":"#b91c1c","button_bg":"#b91c1c","button_text":"#ffffff","border":"#e7e5e4"},"web":{"font":"Lora, Georgia, serif","heading_font":"Lora, Georgia, serif","text":"#1c1917","accent":"#b91c1c","accent_text":"#ffffff"}}', 0, 'Seasonal', 1793500000002, 1793500000002);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_photo_roundup', NULL, 'Visual roundup', 'post', 'Image-led weekly roundup: each story gets a thumbnail beside a kicker, headline and summary. Great for design, travel and culture newsletters.', '{"blocks":[{"id":"x1m","type":"paragraph","data":{"html":"Happy {{date}}, {{subscriber.first_name|there}}! Five things that caught our eye this week — skim the pictures, stay for the stories."}},{"id":"x1n","type":"divider","data":{"style":"line"}},{"id":"x1s","type":"columns","data":{"valign":"middle","columns":[{"blocks":[{"id":"x1o","type":"image","data":{"src":"/static/templates/story-a.jpg","alt":"","title":"","caption":"","width":100,"align":"center","link":"","radius":8}}]},{"blocks":[{"id":"x1p","type":"paragraph","data":{"html":"<b>CITIES</b>"}},{"id":"x1q","type":"heading","data":{"level":3,"html":"The skyline that rebuilt itself"}},{"id":"x1r","type":"paragraph","data":{"html":"Two sentences on why this story matters and what readers will learn. <a href=\"https://example.com\">Read more →</a>"}}]}]}},{"id":"x1x","type":"columns","data":{"valign":"middle","columns":[{"blocks":[{"id":"x1t","type":"image","data":{"src":"/static/templates/story-b.jpg","alt":"","title":"","caption":"","width":100,"align":"center","link":"","radius":8}}]},{"blocks":[{"id":"x1u","type":"paragraph","data":{"html":"<b>TRAVEL</b>"}},{"id":"x1v","type":"heading","data":{"level":3,"html":"Chasing the last sunset of summer"}},{"id":"x1w","type":"paragraph","data":{"html":"A vivid summary in the voice of your publication. Keep it under 40 words. <a href=\"https://example.com\">Read more →</a>"}}]}]}},{"id":"x22","type":"columns","data":{"valign":"middle","columns":[{"blocks":[{"id":"x1y","type":"image","data":{"src":"/static/templates/story-c.jpg","alt":"","title":"","caption":"","width":100,"align":"center","link":"","radius":8}}]},{"blocks":[{"id":"x1z","type":"paragraph","data":{"html":"<b>DESIGN</b>"}},{"id":"x20","type":"heading","data":{"level":3,"html":"Patterns hiding in plain sight"}},{"id":"x21","type":"paragraph","data":{"html":"One surprising detail that makes people want to click through. <a href=\"https://example.com\">Read more →</a>"}}]}]}},{"id":"x23","type":"divider","data":{"style":"line"}},{"id":"x24","type":"heading","data":{"level":3,"html":"Quick hits"}},{"id":"x25","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\">A short link</a> — one line of context","<a href=\"https://example.com\">Another short link</a> — one line of context","<a href=\"https://example.com\">A third short link</a> — one line of context"]}},{"id":"x26","type":"referral","data":{"title":"Know someone with good taste? Share {{publication.name}}"}}]}', '{"email":{"radius":6,"width":640,"spacing":16,"font_size":16,"line_height":1.65,"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","text":"#111111","muted":"#6b6b6b","bg":"#f5f5f4","content_bg":"#ffffff","accent":"#ea580c","link":"#c2410c","button_bg":"#111111","button_text":"#ffffff","border":"#e7e5e4"},"web":{"font":"DM Sans, -apple-system, sans-serif","heading_font":"DM Sans, -apple-system, sans-serif","text":"#111111","accent":"#ea580c","accent_text":"#ffffff"}}', 0, 'Curation', 1793500000003, 1793500000003);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_minimal_letter', NULL, 'Minimal letter', 'post', 'Just words: a quiet, serif, single-column letter with generous spacing — the newsletter equivalent of a handwritten note.', '{"blocks":[{"id":"x27","type":"paragraph","data":{"html":"{{date}}"}},{"id":"x28","type":"paragraph","data":{"html":"Dear {{subscriber.first_name|reader}},"}},{"id":"x29","type":"paragraph","data":{"html":"Start in the middle of a thought. The best letters skip the throat-clearing and begin with the thing you can’t stop thinking about."}},{"id":"x2a","type":"paragraph","data":{"html":"Give it room. Short paragraphs, plain words, one idea at a time. Resist the urge to add images, buttons or headlines — the restraint is the design."}},{"id":"x2b","type":"paragraph","data":{"html":"If there’s something you want the reader to do, ask for it the way you would ask a friend: once, plainly, near the end. <a href=\"https://example.com\">Like this</a>."}},{"id":"x2c","type":"paragraph","data":{"html":"Until next time,"}},{"id":"x2d","type":"paragraph","data":{"html":"<i>— Your name</i>"}},{"id":"x2e","type":"divider","data":{"style":"space"}},{"id":"x2f","type":"paragraph","data":{"html":"<small>P.S. A postscript is the second most-read line in any letter. Use it for the one thing you really want them to remember.</small>"}}]}', '{"email":{"radius":2,"width":580,"spacing":20,"font_size":18,"line_height":1.8,"font":"Georgia, ''Times New Roman'', serif","heading_font":"Georgia, ''Times New Roman'', serif","text":"#292524","muted":"#a8a29e","bg":"#f5f1e8","content_bg":"#fffcf5","accent":"#292524","link":"#292524","button_bg":"#292524","button_text":"#fffcf5","border":"#e7e0d0"},"web":{"font":"Libre Baskerville, Georgia, serif","heading_font":"Libre Baskerville, Georgia, serif","text":"#292524","accent":"#292524","accent_text":"#fffcf5","bg":"#fffcf5"}}', 0, 'Editorial', 1793500000004, 1793500000004);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_magazine', NULL, 'Magazine two-column', 'post', 'Magazine-style issue: big cover image, a featured story, a two-column grid of articles and an “also in this issue” rail.', '{"blocks":[{"id":"x2g","type":"image","data":{"src":"/static/templates/mag-hero.jpg","alt":"Cover","title":"","caption":"","width":100,"align":"center","link":"","radius":0}},{"id":"x2h","type":"paragraph","data":{"html":"<b style=\"color:#dc2626\">COVER STORY</b>"}},{"id":"x2i","type":"heading","data":{"level":1,"html":"The headline that makes this issue worth opening"}},{"id":"x2j","type":"paragraph","data":{"html":"A deck of two sentences that sets up the cover story: the tension, the stakes, and why now. Then link to the full piece."}},{"id":"x2k","type":"button","data":{"label":"Read the cover story","url":"https://example.com","align":"left","bg":"#111827"}},{"id":"x2l","type":"divider","data":{"style":"line","color":"#111827"}},{"id":"x2u","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"x2m","type":"image","data":{"src":"/static/templates/story-a.jpg","alt":"","title":"","caption":"","width":100,"align":"center","link":"","radius":4}},{"id":"x2n","type":"paragraph","data":{"html":"<b style=\"color:#dc2626\">ESSAY</b>"}},{"id":"x2o","type":"heading","data":{"level":3,"html":"A smart second story"}},{"id":"x2p","type":"paragraph","data":{"html":"Short summary, one hook, one link. <a href=\"https://example.com\">Read →</a>"}}]},{"blocks":[{"id":"x2q","type":"image","data":{"src":"/static/templates/story-b.jpg","alt":"","title":"","caption":"","width":100,"align":"center","link":"","radius":4}},{"id":"x2r","type":"paragraph","data":{"html":"<b style=\"color:#dc2626\">REPORT</b>"}},{"id":"x2s","type":"heading","data":{"level":3,"html":"A reported third story"}},{"id":"x2t","type":"paragraph","data":{"html":"Short summary, one hook, one link. <a href=\"https://example.com\">Read →</a>"}}]}]}},{"id":"x33","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"x2v","type":"image","data":{"src":"/static/templates/story-c.jpg","alt":"","title":"","caption":"","width":100,"align":"center","link":"","radius":4}},{"id":"x2w","type":"paragraph","data":{"html":"<b style=\"color:#dc2626\">CULTURE</b>"}},{"id":"x2x","type":"heading","data":{"level":3,"html":"Something to look at"}},{"id":"x2y","type":"paragraph","data":{"html":"Short summary, one hook, one link. <a href=\"https://example.com\">Read →</a>"}}]},{"blocks":[{"id":"x2z","type":"image","data":{"src":"/static/templates/event-2.jpg","alt":"","title":"","caption":"","width":100,"align":"center","link":"","radius":4}},{"id":"x30","type":"paragraph","data":{"html":"<b style=\"color:#dc2626\">PEOPLE</b>"}},{"id":"x31","type":"heading","data":{"level":3,"html":"Someone to meet"}},{"id":"x32","type":"paragraph","data":{"html":"Short summary, one hook, one link. <a href=\"https://example.com\">Read →</a>"}}]}]}},{"id":"x36","type":"section","data":{"blocks":[{"id":"x34","type":"heading","data":{"level":4,"html":"ALSO IN THIS ISSUE"}},{"id":"x35","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\">Letters to the editor</a>","<a href=\"https://example.com\">The crossword</a>","<a href=\"https://example.com\">What we’re reading</a>"]}}],"style":{"bg":"#f3f4f6","padding":18,"radius":0}}}]}', '{"email":{"radius":0,"width":680,"spacing":16,"font_size":16,"line_height":1.65,"font":"Georgia, ''Times New Roman'', serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","text":"#111827","muted":"#6b7280","bg":"#e5e7eb","content_bg":"#ffffff","accent":"#dc2626","link":"#b91c1c","button_bg":"#111827","button_text":"#ffffff","border":"#d1d5db"},"web":{"font":"Source Serif 4, Georgia, serif","heading_font":"Playfair Display, Georgia, serif","text":"#111827","accent":"#dc2626","accent_text":"#ffffff"}}', 0, 'Editorial', 1793500000005, 1793500000005);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_recipe', NULL, 'Recipe card', 'post', 'Recipe or step-by-step how-to: hero photo, time/serves table, an ingredient checklist, numbered steps and a pro tip.', '{"blocks":[{"id":"x37","type":"image","data":{"src":"/static/templates/recipe.jpg","alt":"The finished dish","title":"","caption":"","width":100,"align":"center","link":"","radius":14}},{"id":"x38","type":"heading","data":{"level":1,"html":"Weeknight tomato & herb soup"}},{"id":"x39","type":"paragraph","data":{"html":"One sentence on why this recipe earns a spot in the rotation — the flavor, the shortcut, the memory."}},{"id":"x3a","type":"table","data":{"rows":[["⏱ Prep","🔥 Cook","🍽 Serves","📈 Level"],["10 min","25 min","4","Easy"]],"header":true}},{"id":"x3b","type":"heading","data":{"level":2,"html":"Ingredients"}},{"id":"x3c","type":"checklist","data":{"items":[{"html":"2 tbsp olive oil","checked":false},{"html":"1 onion, finely chopped","checked":false},{"html":"3 cloves garlic","checked":false},{"html":"800 g ripe tomatoes (or 2 tins)","checked":false},{"html":"A handful of basil, salt and pepper","checked":false}]}},{"id":"x3d","type":"heading","data":{"level":2,"html":"Method"}},{"id":"x3e","type":"list","data":{"ordered":true,"items":["<b>Soften.</b> Warm the oil and cook the onion gently for 8 minutes until sweet.","<b>Build.</b> Add garlic for one minute, then the tomatoes and a pinch of salt.","<b>Simmer.</b> Cover and cook 15 minutes, stirring now and then.","<b>Finish.</b> Blend until smooth, taste, and tear in the basil."]}},{"id":"x3g","type":"section","data":{"blocks":[{"id":"x3f","type":"paragraph","data":{"html":"💡 <b>Pro tip:</b> a spoon of butter stirred in at the end rounds out acidic tomatoes. Swap for olive oil to keep it vegan."}}],"style":{"bg":"#fffbeb","padding":18,"radius":12,"border_width":1,"border_color":"#fde68a"}}},{"id":"x3h","type":"paragraph","data":{"html":"Made it? Hit reply with a photo — we feature reader kitchens every month."}}]}', '{"email":{"radius":14,"width":640,"spacing":16,"font_size":16,"line_height":1.65,"font":"''Trebuchet MS'', Helvetica, sans-serif","heading_font":"Georgia, ''Times New Roman'', serif","text":"#292524","muted":"#78716c","bg":"#fef3c7","content_bg":"#ffffff","accent":"#ea580c","link":"#c2410c","button_bg":"#ea580c","button_text":"#ffffff","border":"#fde68a"},"web":{"font":"Work Sans, -apple-system, sans-serif","heading_font":"Fraunces, Georgia, serif","text":"#292524","accent":"#ea580c","accent_text":"#ffffff"}}', 0, 'Education', 1793500000006, 1793500000006);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_event_recap', NULL, 'Event recap', 'post', 'Post-event follow-up: thank-you banner, photo grid, highlights, the best quote, replay link and a save-the-date for next time.', '{"blocks":[{"id":"x3i","type":"image","data":{"src":"/static/templates/event-3.jpg","alt":"Thank you","title":"","caption":"","width":100,"align":"center","link":"","radius":12}},{"id":"x3j","type":"heading","data":{"level":1,"html":"That was something, {{subscriber.first_name|friend}}"}},{"id":"x3k","type":"paragraph","data":{"html":"Thank everyone who came, by number if it’s impressive (“412 of you joined live from 31 countries”). Then promise the good stuff below."}},{"id":"x3l","type":"gallery","data":{"images":[{"src":"/static/templates/event-1.jpg","alt":"Main stage","caption":"Main stage"},{"src":"/static/templates/event-2.jpg","alt":"Speakers","caption":"Our speakers"}],"columns":2,"layout":"grid"}},{"id":"x3m","type":"heading","data":{"level":2,"html":"Five highlights"}},{"id":"x3n","type":"list","data":{"ordered":true,"items":["<b>The big announcement</b> — what was revealed and why it matters","<b>Best talk</b> — one takeaway in one sentence","<b>Surprise moment</b> — the thing people tweeted about","<b>By the numbers</b> — attendees, questions, coffees","<b>What we’d change</b> — honesty builds trust"]}},{"id":"x3o","type":"quote","data":{"html":"“The most useful two hours I’ve spent this year.”","cite":"An attendee, via the feedback form","style":{"variant":"box","border_color":"#7c3aed","border_width":2,"italic":true,"bg":"#faf5ff"}}},{"id":"x3r","type":"columns","data":{"valign":"middle","columns":[{"blocks":[{"id":"x3p","type":"button","data":{"label":"▶ Watch the replay","url":"https://example.com","align":"center","bg":"#7c3aed"}}]},{"blocks":[{"id":"x3q","type":"button","data":{"label":"Download the slides","url":"https://example.com","align":"center","bg":"#ede9fe","color":"#5b21b6"}}]}]}},{"id":"x3w","type":"section","data":{"blocks":[{"id":"x3s","type":"paragraph","data":{"html":"<b style=\"color:#7c3aed;letter-spacing:2px\">SAVE THE DATE</b>","align":"center"}},{"id":"x3t","type":"heading","data":{"level":2,"html":"Next edition: March 14 · Online","align":"center"}},{"id":"x3u","type":"paragraph","data":{"html":"Early-bird spots open to newsletter readers first.","align":"center"}},{"id":"x3v","type":"button","data":{"label":"Get early access","url":"https://example.com","align":"center","bg":"#1e1b4b"}}],"style":{"bg":"#ede9fe","padding":24,"radius":12,"border_width":1,"border_color":"#c4b5fd"}}}]}', '{"email":{"radius":12,"width":640,"spacing":16,"font_size":16,"line_height":1.65,"font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","heading_font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","text":"#1e1b4b","muted":"#6b7280","bg":"#ede9fe","content_bg":"#ffffff","accent":"#7c3aed","link":"#6d28d9","button_bg":"#7c3aed","button_text":"#ffffff","border":"#ddd6fe"},"web":{"font":"Space Grotesk, -apple-system, sans-serif","heading_font":"Space Grotesk, -apple-system, sans-serif","text":"#1e1b4b","accent":"#7c3aed","accent_text":"#ffffff"}}', 0, 'Media & events', 1793500000007, 1793500000007);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_investor_update', NULL, 'Investor update', 'post', 'Monthly investor / stakeholder letter: TL;DR, KPI table, highlights and lowlights, asks, and the cash position — crisp and skimmable.', '{"blocks":[{"id":"x3x","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|all}},"}},{"id":"x3y","type":"paragraph","data":{"html":"Here’s our update for the month. As always, the TL;DR first, then the details."}},{"id":"x41","type":"section","data":{"blocks":[{"id":"x3z","type":"heading","data":{"level":4,"html":"TL;DR"}},{"id":"x40","type":"list","data":{"ordered":false,"items":["Revenue up X% month over month to $Y MRR","Shipped the feature customers asked for most","Hiring: one senior engineer — intros welcome"]}}],"style":{"bg":"#f8fafc","padding":18,"radius":6,"border_width":1,"border_color":"#cbd5e1"}}},{"id":"x42","type":"heading","data":{"level":2,"html":"Key metrics"}},{"id":"x43","type":"table","data":{"rows":[["Metric","This month","Last month","Change"],["MRR","$48,200","$43,100","<b style=\"color:#15803d\">+11.8%</b>"],["Customers","312","287","<b style=\"color:#15803d\">+8.7%</b>"],["Net revenue retention","118%","115%","<b style=\"color:#15803d\">+3 pts</b>"],["Burn","$61,000","$64,500","<b style=\"color:#15803d\">−5.4%</b>"],["Runway","22 months","21 months","—"]],"header":true}},{"id":"x48","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"x44","type":"heading","data":{"level":3,"html":"✅ Highlights"}},{"id":"x45","type":"list","data":{"ordered":false,"items":["A specific win with a number","A customer or partnership","A team milestone"]}}]},{"blocks":[{"id":"x46","type":"heading","data":{"level":3,"html":"⚠️ Lowlights"}},{"id":"x47","type":"list","data":{"ordered":false,"items":["What didn’t go to plan","What you learned","What you’re changing"]}}]}]}},{"id":"x49","type":"heading","data":{"level":2,"html":"Asks"}},{"id":"x4a","type":"list","data":{"ordered":true,"items":["<b>Intros:</b> heads of operations at mid-size logistics companies","<b>Hiring:</b> senior backend engineers (remote, EU time zones)","<b>Advice:</b> anyone who has priced usage-based plans"]}},{"id":"x4b","type":"paragraph","data":{"html":"Thanks for your support — reply anytime, I read everything."}},{"id":"x4c","type":"paragraph","data":{"html":"<b>Your name</b><br>Founder &amp; CEO"}}]}', '{"email":{"radius":4,"width":640,"spacing":16,"font_size":15,"line_height":1.6,"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","text":"#0f172a","muted":"#64748b","bg":"#f1f5f9","content_bg":"#ffffff","accent":"#0f172a","link":"#1d4ed8","button_bg":"#0f172a","button_text":"#ffffff","border":"#cbd5e1"},"web":{"font":"IBM Plex Sans, -apple-system, sans-serif","heading_font":"IBM Plex Sans, -apple-system, sans-serif","text":"#0f172a","accent":"#0f172a","accent_text":"#ffffff"}}', 0, 'Business', 1793500000008, 1793500000008);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_local_news', NULL, 'Local news bulletin', 'post', 'Neighborhood newsletter: weather and at-a-glance box, top local stories, a community calendar and a local business spotlight.', '{"blocks":[{"id":"x4d","type":"paragraph","data":{"html":"Good morning, {{subscriber.first_name|neighbor}}! It’s {{date}}. Here’s what’s happening around town."}},{"id":"x4i","type":"section","data":{"blocks":[{"id":"x4h","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"x4e","type":"paragraph","data":{"html":"<b>☀️ Today</b><br>Sunny, high of 22°, light breeze from the west."}}]},{"blocks":[{"id":"x4f","type":"paragraph","data":{"html":"<b>🚧 Heads up</b><br>Main St closed between 3rd and 5th until Friday."}}]},{"blocks":[{"id":"x4g","type":"paragraph","data":{"html":"<b>🗳 Reminder</b><br>Council meeting Thursday at 7pm, City Hall."}}]}]}}],"style":{"bg":"#eff6ff","padding":16,"radius":8,"border_width":1,"border_color":"#bfdbfe"}}},{"id":"x4j","type":"heading","data":{"level":2,"html":"Top stories"}},{"id":"x4k","type":"paragraph","data":{"html":"<b>New park opens on the riverfront.</b> Two to three sentences: what, where, when, and what it means for residents. <a href=\"https://example.com\">Full story →</a>"}},{"id":"x4l","type":"paragraph","data":{"html":"<b>School board approves later start times.</b> Lead with the decision, then the vote, then what happens next. <a href=\"https://example.com\">Full story →</a>"}},{"id":"x4m","type":"paragraph","data":{"html":"<b>Farmers market adds a Wednesday evening.</b> A friendly, useful update readers will forward. <a href=\"https://example.com\">Full story →</a>"}},{"id":"x4n","type":"heading","data":{"level":2,"html":"This week’s calendar"}},{"id":"x4o","type":"table","data":{"rows":[["When","What","Where"],["Wed 6pm","Farmers market","Riverside Plaza"],["Thu 7pm","City council meeting","City Hall"],["Sat 10am","Kids’ book swap","Central Library"],["Sun 9am","Community 5K","North Park"]],"header":true}},{"id":"x4p","type":"ad","data":{"label":"Local business spotlight","headline":"Corner Bakery turns 25 this week","body":"Stop by Saturday for free coffee with any pastry — a thank-you to the neighborhood that kept them baking.","url":"https://example.com","cta":"See the menu"}},{"id":"x4q","type":"paragraph","data":{"html":"Got a tip, photo or event? Just hit reply — we read every message."}}]}', '{"email":{"radius":8,"width":640,"spacing":16,"font_size":15,"line_height":1.65,"font":"Verdana, Geneva, sans-serif","heading_font":"Georgia, ''Times New Roman'', serif","text":"#1e293b","muted":"#64748b","bg":"#e2e8f0","content_bg":"#ffffff","accent":"#1d4ed8","link":"#1d4ed8","button_bg":"#1d4ed8","button_text":"#ffffff","border":"#cbd5e1"},"web":{"font":"Open Sans, -apple-system, sans-serif","heading_font":"Merriweather, Georgia, serif","text":"#1e293b","accent":"#1d4ed8","accent_text":"#ffffff"}}', 0, 'Digest', 1793500000009, 1793500000009);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_job_board', NULL, 'Job board', 'post', 'Weekly hiring newsletter: featured roles as cards with apply buttons, a scannable table of more openings and a “post a job” CTA for employers.', '{"blocks":[{"id":"x4r","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}}, here are this week’s hand-picked roles. Every listing is verified and includes a salary range."}},{"id":"x4s","type":"heading","data":{"level":2,"html":"⭐ Featured roles"}},{"id":"x4w","type":"section","data":{"blocks":[{"id":"x4t","type":"paragraph","data":{"html":"<b style=\"font-size:17px\">Senior Product Designer</b><br><span style=\"color:#64748b\">Northwind · Remote (EU) · $110–140k</span>"}},{"id":"x4u","type":"paragraph","data":{"html":"Lead design for a fast-growing logistics platform. You’ll own the end-to-end experience for shippers."}},{"id":"x4v","type":"button","data":{"label":"Apply →","url":"https://example.com","align":"left","bg":"#0d9488"}}],"style":{"bg":"#ffffff","padding":18,"radius":10,"border_width":1,"border_color":"#cbd5e1"}}},{"id":"x50","type":"section","data":{"blocks":[{"id":"x4x","type":"paragraph","data":{"html":"<b style=\"font-size:17px\">Staff Backend Engineer</b><br><span style=\"color:#64748b\">Contoso Labs · New York or remote · $180–210k</span>"}},{"id":"x4y","type":"paragraph","data":{"html":"Scale the event pipeline behind 2B requests a day. Go, Postgres, Kafka."}},{"id":"x4z","type":"button","data":{"label":"Apply →","url":"https://example.com","align":"left","bg":"#0d9488"}}],"style":{"bg":"#ffffff","padding":18,"radius":10,"border_width":1,"border_color":"#cbd5e1"}}},{"id":"x51","type":"heading","data":{"level":2,"html":"More openings"}},{"id":"x52","type":"table","data":{"rows":[["Role","Company","Location","Salary"],["<a href=\"https://example.com\">Data Analyst</a>","Fabrikam","Remote (US)","$85–105k"],["<a href=\"https://example.com\">Content Lead</a>","Tailspin","London","£60–70k"],["<a href=\"https://example.com\">DevRel Engineer</a>","Adatum","Remote","$130–150k"],["<a href=\"https://example.com\">Customer Success Manager</a>","Litware","Berlin","€65–75k"]],"header":true}},{"id":"x56","type":"section","data":{"blocks":[{"id":"x53","type":"heading","data":{"level":3,"html":"Hiring? Reach 40,000 qualified readers","align":"center"}},{"id":"x54","type":"paragraph","data":{"html":"Featured listings include a card in the newsletter and a month on the job board.","align":"center"}},{"id":"x55","type":"button","data":{"label":"Post a job","url":"https://example.com","align":"center","bg":"#0f172a"}}],"style":{"bg":"#ccfbf1","padding":22,"radius":12}}}]}', '{"email":{"radius":10,"width":640,"spacing":16,"font_size":16,"line_height":1.65,"font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","heading_font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","text":"#0f172a","muted":"#64748b","bg":"#f0fdfa","content_bg":"#f8fafc","accent":"#0d9488","link":"#0f766e","button_bg":"#0d9488","button_text":"#ffffff","border":"#cbd5e1"},"web":{"font":"Manrope, -apple-system, sans-serif","heading_font":"Manrope, -apple-system, sans-serif","text":"#0f172a","accent":"#0d9488","accent_text":"#ffffff"}}', 0, 'Curation', 1793500000010, 1793500000010);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_ama', NULL, 'Ask me anything', 'post', 'Q&A issue answering reader questions: each question in a highlighted card with the asker’s name, followed by a candid answer and a prompt to ask the next one.', '{"blocks":[{"id":"x57","type":"heading","data":{"level":1,"html":"You asked, I answered 🙋"}},{"id":"x58","type":"paragraph","data":{"html":"Every month I pick the best questions from your replies. This month: careers, tools and one spicy one. Names shared with permission."}},{"id":"x5a","type":"section","data":{"blocks":[{"id":"x59","type":"paragraph","data":{"html":"<b>Q: How do you decide what to write about each week?</b><br><span style=\"color:#9a3412;font-size:14px\">— Priya, Toronto</span>"}}],"style":{"bg":"#fff7ed","padding":16,"radius":10,"border_width":0}}},{"id":"x5b","type":"paragraph","data":{"html":"Answer conversationally. Share the actual process — the messy notes app, the shower thoughts, the reader replies that spark entire issues."}},{"id":"x5d","type":"section","data":{"blocks":[{"id":"x5c","type":"paragraph","data":{"html":"<b>Q: What’s one tool you couldn’t work without?</b><br><span style=\"color:#9a3412;font-size:14px\">— Marco, Lisbon</span>"}}],"style":{"bg":"#fff7ed","padding":16,"radius":10,"border_width":0}}},{"id":"x5e","type":"paragraph","data":{"html":"Be specific and honest, including the downsides. Readers trust recommendations that admit trade-offs."}},{"id":"x5g","type":"section","data":{"blocks":[{"id":"x5f","type":"paragraph","data":{"html":"<b>Q: What would you do differently if you started today?</b><br><span style=\"color:#9a3412;font-size:14px\">— Sam, Austin</span>"}}],"style":{"bg":"#fff7ed","padding":16,"radius":10,"border_width":0}}},{"id":"x5h","type":"paragraph","data":{"html":"The most-read answer is usually the most vulnerable one. Share a real mistake and what it cost you."}},{"id":"x5i","type":"divider","data":{"style":"dots"}},{"id":"x5m","type":"section","data":{"blocks":[{"id":"x5j","type":"heading","data":{"level":3,"html":"Got a question for next month?","align":"center"}},{"id":"x5k","type":"paragraph","data":{"html":"Reply to this email or use the form — anything goes.","align":"center"}},{"id":"x5l","type":"button","data":{"label":"Ask a question","url":"https://example.com","align":"center","bg":"#c2410c"}}],"style":{"bg":"#ffedd5","padding":22,"radius":12}}}]}', '{"email":{"radius":12,"width":640,"spacing":16,"font_size":16,"line_height":1.65,"font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","heading_font":"Georgia, ''Times New Roman'', serif","text":"#1c1917","muted":"#78716c","bg":"#fff7ed","content_bg":"#ffffff","accent":"#ea580c","link":"#c2410c","button_bg":"#c2410c","button_text":"#ffffff","border":"#fed7aa"},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"Fraunces, Georgia, serif","text":"#1c1917","accent":"#c2410c","accent_text":"#ffffff"}}', 0, 'Editorial', 1793500000011, 1793500000011);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_shop_picks', NULL, 'Shop picks for you', 'post', 'Commerce issue with a personalized “picked for you” block — every reader sees products they haven’t bought yet, ranked by what similar readers bought and their interests.', '{"blocks":[{"id":"x5n","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}} — a quick one this week. We pulled together a few things we think you’ll like, based on what readers like you have been enjoying."}},{"id":"x5o","type":"recommended_products","data":{"title":"Picked for you","limit":3,"cta":"Take a look"}},{"id":"x5p","type":"heading","data":{"level":2,"html":"New this month"}},{"id":"x5u","type":"columns","data":{"valign":"middle","columns":[{"blocks":[{"id":"x5q","type":"image","data":{"src":"/static/templates/product-1.jpg","alt":"New guide","title":"","caption":"","width":100,"align":"center","link":"","radius":10}}]},{"blocks":[{"id":"x5r","type":"heading","data":{"level":3,"html":"The field guide, second edition"}},{"id":"x5s","type":"paragraph","data":{"html":"Two sentences on what’s new and who it’s for. Mention the format and what readers get immediately after buying."}},{"id":"x5t","type":"button","data":{"label":"See what’s inside","url":"https://example.com","align":"left"}}]}]}},{"id":"x5w","type":"section","data":{"blocks":[{"id":"x5v","type":"paragraph","data":{"html":"<b>Members save 20%</b> on everything in the shop — it’s applied automatically at checkout when you’re signed in.","align":"center"}}],"style":{"bg":"#f0f9ff","padding":16,"radius":10}}},{"id":"x5x","type":"paragraph","data":{"html":"Thanks for supporting independent work. Every purchase keeps this newsletter free for everyone."}}]}', '{"email":{"radius":12,"width":640,"spacing":16,"font_size":16,"line_height":1.65,"font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","heading_font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","text":"#0c4a6e","muted":"#64748b","bg":"#e0f2fe","content_bg":"#ffffff","accent":"#0284c7","link":"#0369a1","button_bg":"#0c4a6e","button_text":"#ffffff","border":"#bae6fd"},"web":{"font":"Poppins, -apple-system, sans-serif","heading_font":"Poppins, -apple-system, sans-serif","text":"#0c4a6e","accent":"#0284c7","accent_text":"#ffffff"}}', 0, 'Business', 1793500000012, 1793500000012);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_coded_starter', NULL, 'Hand-coded HTML starter', 'post', 'A custom-coded template: one full HTML document sent exactly as written (responsive tables, dark hero, two columns). Use it as a starting point for your own code.', '{"blocks":[{"id":"x5y","type":"html_document","data":{"html":"<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>{{publication.name}}</title>\n<style>\n  body{margin:0;padding:0;background:#0b1220;-webkit-text-size-adjust:100%}\n  a{color:#38bdf8}\n  .wrap{width:600px;max-width:100%}\n  @media only screen and (max-width:620px){.wrap{width:100%!important}.col{display:block!important;width:100%!important}.pad{padding:24px!important}h1{font-size:28px!important}}\n</style></head>\n<body>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#0b1220\"><tr><td align=\"center\" style=\"padding:32px 12px\">\n  <table role=\"presentation\" class=\"wrap\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n    <tr><td style=\"padding:0 0 18px;font-family:Helvetica,Arial,sans-serif;font-size:13px;color:#94a3b8\">{{publication.name}} · <a href=\"{{web_url}}\" style=\"color:#94a3b8\">View in browser</a></td></tr>\n    <tr><td class=\"pad\" bgcolor=\"#111a2e\" style=\"padding:44px;border-radius:16px 16px 0 0;background:#111a2e;background-image:linear-gradient(135deg,#1e3a8a,#0f766e)\">\n      <p style=\"margin:0 0 10px;font-family:Helvetica,Arial,sans-serif;font-size:12px;letter-spacing:3px;color:#a5f3fc\">HAND-CODED EDITION</p>\n      <h1 style=\"margin:0 0 14px;font-family:Helvetica,Arial,sans-serif;font-size:36px;line-height:1.15;color:#ffffff\">Hello {{subscriber.first_name|there}}, this email is pure HTML</h1>\n      <p style=\"margin:0;font-family:Helvetica,Arial,sans-serif;font-size:17px;line-height:1.6;color:#e2e8f0\">Paste your own design in Templates → New coded template. Merge tags work, links are tracked, and the unsubscribe link is filled in for you.</p>\n    </td></tr>\n    <tr><td class=\"pad\" bgcolor=\"#ffffff\" style=\"padding:36px 44px;background:#ffffff\">\n      <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n        <td class=\"col\" width=\"50%\" valign=\"top\" style=\"padding:0 12px 16px 0;font-family:Helvetica,Arial,sans-serif\">\n          <p style=\"margin:0 0 6px;font-size:28px\">🎨</p><p style=\"margin:0 0 6px;font-size:17px;font-weight:700;color:#0f172a\">Your design, exactly</p>\n          <p style=\"margin:0;font-size:15px;line-height:1.6;color:#475569\">Bring HTML from any builder or your design team. It’s sent as written — no wrappers.</p></td>\n        <td class=\"col\" width=\"50%\" valign=\"top\" style=\"padding:0 0 16px 12px;font-family:Helvetica,Arial,sans-serif\">\n          <p style=\"margin:0 0 6px;font-size:28px\">🛡️</p><p style=\"margin:0 0 6px;font-size:17px;font-weight:700;color:#0f172a\">Safe by default</p>\n          <p style=\"margin:0;font-size:15px;line-height:1.6;color:#475569\">Scripts and unsafe attributes are stripped; on the web it renders in a sandbox.</p></td>\n      </tr></table>\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:12px 0 0\"><tr><td bgcolor=\"#0f766e\" style=\"border-radius:999px;background:#0f766e\"><a href=\"https://example.com\" style=\"display:inline-block;padding:14px 28px;font-family:Helvetica,Arial,sans-serif;font-size:16px;font-weight:700;color:#ffffff;text-decoration:none;border-radius:999px\">Read the guide →</a></td></tr></table>\n    </td></tr>\n    <tr><td style=\"padding:24px 44px;border-radius:0 0 16px 16px;background:#f1f5f9;font-family:Helvetica,Arial,sans-serif;font-size:12px;line-height:1.7;color:#64748b;text-align:center\">\n      You’re receiving this because you subscribed to {{publication.name}}.<br>\n      <a href=\"{{preferences_url}}\" style=\"color:#64748b\">Manage preferences</a> · <a href=\"{{unsubscribe_url}}\" style=\"color:#64748b\">Unsubscribe</a>\n    </td></tr>\n  </table>\n</td></tr></table>\n</body></html>"}}]}', '{"email":{"radius":10,"width":640,"spacing":16,"font_size":16,"line_height":1.65},"web":{}}', 0, 'Coded', 1793500000013, 1793500000013);
